package com.smartmart.common.seed;

import com.smartmart.inventory.entity.Inventory; import com.smartmart.inventory.repository.InventoryRepository; import com.smartmart.order.entity.*; import com.smartmart.order.repository.CustomerOrderRepository; import com.smartmart.product.entity.Product; import com.smartmart.product.repository.ProductRepository; import com.smartmart.user.entity.*; import com.smartmart.user.repository.UserRepository; import com.smartmart.wishlist.entity.Wishlist; import com.smartmart.wishlist.repository.WishlistRepository;
import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;

/** Explicit opt-in development data. It only runs against an empty catalogue and never deletes data. */
@Component @RequiredArgsConstructor @ConditionalOnProperty(name="smartmart.demo-seed", havingValue="true")
public class DemoDataSeeder implements CommandLineRunner { private final ProductRepository products; private final InventoryRepository inventory; private final UserRepository users; private final WishlistRepository wishlists; private final CustomerOrderRepository orders; private final PasswordEncoder encoder;
 @Override @Transactional public void run(String... args){ if(products.count()>0)return; List<Product> ps=new ArrayList<>(); String[][] rows={{"Rolled Oats","Quaker","Pantry","349","C","3","Whole grain breakfast oats"},{"Natural Peanut Butter","Pintola","Pantry","299","C","4","Unsweetened peanut butter"},{"Whey Protein","Optimum Nutrition","Nutrition","2499","D","2","Chocolate protein powder"},{"Protein Bar","Yoga Bar","Nutrition","89","D","3","Peanut butter protein snack"},{"Toned Milk","Amul","Dairy","64","A","1","Fresh toned milk"},{"Greek Yogurt","Epigamia","Dairy","120","A","2","High protein yogurt"},{"Whole Wheat Bread","Britannia","Bakery","52","B","1","Fresh whole wheat loaf"},{"Multigrain Bread","Modern","Bakery","58","B","2","Seeded multigrain loaf"},{"Basmati Rice","India Gate","Pantry","699","C","1","Premium basmati rice"},{"Toor Dal","Tata Sampann","Pantry","210","C","2","Unpolished pigeon peas"},{"Classic Tea","Tata Tea","Beverages","180","E","1","Black tea leaves"},{"Instant Coffee","Nescafe","Beverages","365","E","2","Rich instant coffee"},{"Orange Juice","Tropicana","Beverages","145","E","3","100 percent fruit juice"},{"Potato Chips","Lay's","Snacks","40","F","1","Classic salted chips"},{"Dark Chocolate","Cadbury","Snacks","110","F","2","70 percent cocoa chocolate"},{"Bananas","Fresh Fields","Produce","60","G","1","Farm fresh bananas"},{"Apples","Fresh Fields","Produce","180","G","2","Crisp red apples"},{"Tomatoes","Fresh Fields","Produce","45","G","3","Vine ripened tomatoes"},{"Dishwash Liquid","Vim","Home Care","115","H","1","Lemon dishwash liquid"},{"Laundry Detergent","Surf Excel","Home Care","320","H","2","Matic detergent"},{"Baby Diapers","Pampers","Baby Care","799","I","1","Comfort fit diapers"},{"Shampoo","Dove","Personal Care","245","I","2","Daily moisture shampoo"},{"Almonds","Happilo","Snacks","425","F","3","Premium roasted almonds"},{"Olive Oil","Borges","Pantry","640","C","5","Extra virgin olive oil"}}; for(String[] r:rows)ps.add(products.save(Product.builder().name(r[0]).brand(r[1]).category(r[2]).price(new BigDecimal(r[3])).aisle(r[4]).shelf(r[5]).description(r[6]).build())); for(int x=0;x<ps.size();x++){int q=switch(x){case 2->3;case 3->7;case 4->2;case 6->0;case 12->48;case 14->60;default->18+x%5*15;}; LocalDate expiry=(x==4?LocalDate.now().plusDays(3):x==6?LocalDate.now().plusDays(6):x==12?LocalDate.now().plusDays(12):x==15?LocalDate.now().plusDays(2):null); BigDecimal discount=(x==3?new BigDecimal("15"):x==12?new BigDecimal("20"):BigDecimal.ZERO);inventory.save(Inventory.builder().product(ps.get(x)).quantity(q).reorderLevel(10).expiryDate(expiry).discountPercentage(discount).build());} User a=users.save(User.builder().name("Demo Shopper").email("demo.shopper@smartmart.local").password(encoder.encode("DemoPass123")).role(Role.SHOPPER).build()); User b=users.save(User.builder().name("Sample Shopper").email("sample.shopper@smartmart.local").password(encoder.encode("DemoPass123")).role(Role.SHOPPER).build()); wishlists.save(Wishlist.builder().user(a).product(ps.get(2)).build());wishlists.save(Wishlist.builder().user(a).product(ps.get(3)).build()); for(int n=0;n<8;n++)createOrder(n%2==0?a:b,ps,List.of(0,1,2,3,10+n%4)); }
 private void createOrder(User user,List<Product> ps,List<Integer> ids){CustomerOrder order=CustomerOrder.builder().user(user).status(OrderStatus.COMPLETED).totalAmount(BigDecimal.ZERO).items(new ArrayList<>()).build();BigDecimal total=BigDecimal.ZERO;for(int id:ids){Product p=ps.get(id);BigDecimal sub=p.getPrice();order.getItems().add(OrderItem.builder().order(order).product(p).quantity(1).unitPrice(p.getPrice()).subtotal(sub).build());total=total.add(sub);}order.setTotalAmount(total);orders.save(order);}
}
